        "starter": "const express = require(\"express\");\nconst fs = require(\"fs\");\nconst app = express();\napp.set(\"view engine\", \"ejs\");\n\napp.get(\"/gallery\", (request, response) => {\n  const data = JSON.parse(fs.readFileSync(\"gallery.json\", \"utf8\"));\n  // Add the selection required by the ticket.\n  const images = data.images;\n  response.render(\"gallery\", { images });\n});\nmodule.exports = app;\n",
