        "starter": "const products=[{\"id\": 1, \"name\": \"Tort\", \"type\": \"cofetarie\", \"price\": 80, \"weight\": 800, \"stock\": 5, \"description\": \"ciocolata neagra\", \"allergen\": \"lapte\", \"promo\": true}, {\"id\": 2, \"name\": \"Corn\", \"type\": \"patiserie\", \"price\": 8, \"weight\": 100, \"stock\": 0, \"description\": \"unt proaspat\", \"allergen\": \"gluten\", \"promo\": false}, {\"id\": 3, \"name\": \"Sorbet\", \"type\": \"gelaterie\", \"price\": 15, \"weight\": 150, \"stock\": 8, \"description\": \"fructe de padure\", \"allergen\": \"none\", \"promo\": true}, {\"id\": 4, \"name\": \"Ecler\", \"type\": \"cofetarie\", \"price\": 12, \"weight\": 120, \"stock\": 2, \"description\": \"crema de vanilie\", \"allergen\": \"gluten\", \"promo\": false}];\ndocument.querySelector(\"#filter\").onclick=()=>{const choice=document.querySelector(\"[name=catalog-filter]:checked\").value;const term=document.querySelector(\"#search\").value.trim().toLowerCase();let total=0;for(const p of products){const visible=(choice===\"all\"||((p.price<=Number(choice.split(\"|\")[0]))&&(p.allergen!==choice.split(\"|\")[1])))&&p.name.toLowerCase().includes(term);document.querySelector(`[data-id=\"${p.id}\"]`).hidden=!visible;if(visible)total++;}document.querySelector(\"#count\").textContent=String(total);};",
