        "solution": "const products=[{\"id\": 1, \"name\": \"Tort\", \"type\": \"cofetarie\", \"price\": 80, \"weight\": 800, \"stock\": 5, \"description\": \"ciocolata neagra\", \"allergen\": \"lapte\", \"promo\": true}, {\"id\": 2, \"name\": \"Corn\", \"type\": \"patiserie\", \"price\": 8, \"weight\": 100, \"stock\": 0, \"description\": \"unt proaspat\", \"allergen\": \"gluten\", \"promo\": false}, {\"id\": 3, \"name\": \"Sorbet\", \"type\": \"gelaterie\", \"price\": 15, \"weight\": 150, \"stock\": 8, \"description\": \"fructe de padure\", \"allergen\": \"none\", \"promo\": true}, {\"id\": 4, \"name\": \"Ecler\", \"type\": \"cofetarie\", \"price\": 12, \"weight\": 120, \"stock\": 2, \"description\": \"crema de vanilie\", \"allergen\": \"gluten\", \"promo\": false}];\ndocument.querySelector(\"#filter\").onclick=()=>{const choice=document.querySelector(\"[name=catalog-filter]:checked\").value;const term=document.querySelector(\"#search\").value.trim().toLowerCase();localStorage.setItem(\"catalogChoice\",choice);let total=0;for(const p of products){const visible=(choice===\"all\"||((p.price<=Number(choice.split(\"|\")[0]))&&(p.weight>=Number(choice.split(\"|\")[1]))&&(p.allergen!==choice.split(\"|\")[2])))&&p.name.toLowerCase().includes(term);document.querySelector(`[data-id=\"${p.id}\"]`).hidden=!visible;if(visible)total++;}document.querySelector(\"#count\").textContent=String(total);};\nconst saved=localStorage.getItem(\"catalogChoice\");for(const radio of document.querySelectorAll(\"[name=catalog-filter]\")){if(radio.value===saved)radio.parentElement.style.border=\"2px solid blue\";}",
